mapper.select:
SELECT p.id, p.name, p.description, p.created_at, p.updated_at, p.created_by, p.is_deleted, p.status, JSON_UNQUOTE(JSON_EXTRACT(p.json_images, '$[0].url')) AS first_image, (SELECT COUNT(*) FROM product_sku ps WHERE ps.product_id = p.id AND ps.is_deleted = 'false') AS sku_count, (SELECT COALESCE(SUM(ps.stock), 0) FROM product_sku ps WHERE ps.product_id = p.id AND ps.is_deleted = 'false') AS total_stock FROM products p WHERE p.is_deleted = 'false'
AND p.status = #{status}
AND LOWER(p.name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
ORDER BY p.created_at DESC, p.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(id) FROM products p WHERE p.is_deleted = 'false'
AND p.status = #{status}
AND LOWER(p.name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
